<?php
namespace App\Filament\Resources;use App\Filament\Resources\ProductCategoryResource\Pages;use App\Models\ProductCategory;use Filament\Resources\Forms\Components;use Filament\Resources\Forms\Form;use Filament\Resources\Resource;use Filament\Resources\Tables\Columns;use Filament\Resources\Tables\Table;
class ProductCategoryResource extends Resource{public static $icon='heroicon-o-collection';public static $label='Danh mục sản phẩm';public static $navigationLabel='Danh mục';public static $navigationSort=51;public static function statusLabels(){return['active'=>'Đang hoạt động','inactive'=>'Ngừng hoạt động'];}public static function form(Form $f){return$f->schema([Components\Select::make('parent_id')->label('Danh mục cha')->options(ProductCategory::pluck('name','id')->toArray()),Components\TextInput::make('name')->label('Tên')->required(),Components\TextInput::make('code')->label('Mã')->required()->unique(static::getModel(),'code',true),Components\Select::make('status')->label('Trạng thái')->options(static::statusLabels())->default('active')->required()]);}public static function table(Table $t){return$t->columns([Columns\Text::make('code')->label('Mã')->primary()->searchable(),Columns\Text::make('name')->label('Tên')->searchable(),Columns\Text::make('parent.name')->label('Danh mục cha'),Columns\Text::make('status')->label('Trạng thái')->options(static::statusLabels())]);}public static function routes(){return[Pages\ListProductCategories::routeTo('/','index'),Pages\CreateProductCategory::routeTo('/create','create'),Pages\EditProductCategory::routeTo('/{record}/edit','edit')];}}
